/**
 * Cross-origin links when Fotomatic (fotomatic.app) needs to point at Grad Drive.
 * Set in `.env.local` for production, e.g. NEXT_PUBLIC_GRADDRIVE_ORIGIN=https://graddrive.com
 */
export function getGradDriveOrigin(): string {
  if (typeof process === 'undefined') return '';
  const raw = process.env.NEXT_PUBLIC_GRADDRIVE_ORIGIN?.trim();
  if (!raw) return '';
  return raw.replace(/\/$/, '');
}

/** Account settings for regular users live under Grad Drive; use absolute URL on Fotomatic host when origin is set. */
export function getGradDriveDashboardAccountUrl(): string {
  const origin = getGradDriveOrigin();
  if (origin) return `${origin}/dashboard/account`;
  return '/dashboard/account';
}
