'use client';

import type { ReactNode } from 'react';
import Image from 'next/image';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { LogOut, User } from 'lucide-react';
import { useAuth } from '@/contexts/AuthContext';
import { signOutUser } from '@/lib/firebase/auth';
import { getGradDriveDashboardAccountUrl } from '@/lib/config/sites';
import { usePhotographerBasePath } from '@/hooks/use-photographer-base-path';

/**
 * Minimal shell for Fotomatic-only clients browsing photographers (no Grad Drive hub menu).
 */
export function FotomaticBrowseShell({
  children,
}: {
  children: ReactNode;
}) {
  const router = useRouter();
  const { user } = useAuth();
  const basePath = usePhotographerBasePath();
  const landingHref = basePath || '/';

  const handleSignOut = async () => {
    await signOutUser();
    router.push(landingHref);
    router.refresh();
  };

  const accountHref = getGradDriveDashboardAccountUrl();

  return (
    <div className='min-h-screen flex flex-col bg-background'>
      <header className='sticky top-0 z-50 w-full border-b border-border/60 bg-background/95 backdrop-blur'>
        <div className='mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between'>
          <Link
            href={landingHref}
            className='flex items-center gap-2 sm:gap-3 shrink-0'
            aria-label='Fotomatic home'
          >
            <Image
              src='/fotomaticImages/fotomaticLogo.png'
              alt=''
              width={44}
              height={44}
              className='h-9 w-9 object-contain'
            />
            <Image
              src='/fotomaticImages/fotomatic.png'
              alt='Fotomatic'
              width={180}
              height={44}
              className='h-7 w-auto max-w-[160px] sm:max-w-[180px] object-contain object-left'
            />
          </Link>

          <div className='flex items-center gap-2'>
            {user ? (
              <>
                <Button variant='ghost' size='sm' asChild>
                  <a
                    href={accountHref}
                    className='gap-2 inline-flex items-center'
                  >
                    <User className='h-4 w-4' />
                    Account
                  </a>
                </Button>
                <Button
                  variant='ghost'
                  size='sm'
                  className='gap-2'
                  onClick={handleSignOut}
                >
                  <LogOut className='h-4 w-4' />
                  Sign out
                </Button>
              </>
            ) : null}
          </div>
        </div>
      </header>
      <main className='flex-1'>{children}</main>
    </div>
  );
}
